	t.Setenv("CLAUDE_PLUGIN_ROOT", "/plugin")
	// specified が真なら、値が空でも「指定あり」として扱い、
	// CLAUDE_PLUGIN_ROOT へフォールバックしない。
	p, origin := resolveJudgmentFlowPath("", true)
